#!/usr/bin/env node

/**
 * Generic Slack Web API wrapper.
 *
 * Usage:
 *   node slack_api.cjs <endpoint> [--method GET|POST] [--data '{"json":...}']
 *       [--paginate] [--max-items N] [--token TOKEN] [--dry-run]
 *
 * - Token resolution: --token flag, else SLACK_TOKEN env var.
 * - Endpoint examples: conversations.list, chat.postMessage.
 * - Prints the JSON response (compact) on success; prints `ERROR <code>` and
 *   exits 1 on failure. No stack traces.
 */

const API_BASE = 'https://slack.com/api/';

function fail(msg) {
  process.stderr.write('ERROR ' + msg + '\n');
  process.exit(1);
}

function parseArgs(argv) {
  if (argv.length < 1) {
    fail(
      'usage: slack_api.cjs <endpoint> [--method GET|POST] [--data JSON] [--paginate] [--max-items N] [--token TOKEN] [--dry-run]',
    );
  }
  const opts = {
    endpoint: argv[0],
    method: 'POST',
    data: undefined,
    paginate: false,
    maxItems: undefined,
    token: process.env.SLACK_TOKEN || undefined,
    dryRun: false,
  };
  for (let i = 1; i < argv.length; i++) {
    const arg = argv[i];
    const next = () => argv[++i];
    switch (arg) {
      case '--method':
        opts.method = String(next() || 'POST').toUpperCase();
        break;
      case '--data':
        try {
          opts.data = JSON.parse(next());
        } catch (e) {
          fail('invalid JSON in --data: ' + e.message);
        }
        break;
      case '--paginate':
        opts.paginate = true;
        break;
      case '--max-items':
        opts.maxItems = Number.parseInt(next(), 10);
        if (Number.isNaN(opts.maxItems) || opts.maxItems < 1) {
          fail('invalid --max-items: expected a positive integer');
        }
        break;
      case '--token':
        opts.token = next();
        break;
      case '--dry-run':
        opts.dryRun = true;
        break;
      default:
        fail('unknown argument: ' + arg);
    }
  }
  if (!opts.token && !opts.dryRun) {
    fail('no token: set SLACK_TOKEN or pass --token');
  }
  return opts;
}

function encodeBody(obj) {
  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(obj || {})) {
    params.set(
      key,
      typeof value === 'object' && value !== null ? JSON.stringify(value) : String(value),
    );
  }
  return params.toString();
}

async function call(opts, url, body) {
  const res = await fetch(url, {
    method: opts.method,
    headers: {
      Authorization: 'Bearer ' + opts.token,
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: body || undefined,
  });
  if (res.status === 429) {
    fail('rate_limited: retry after ' + (res.headers.get('Retry-After') || 'unknown') + 's');
  }
  if (!res.ok) fail('http_' + res.status);
  return res.json();
}

function mergePages(pages) {
  const merged = {};
  for (const key of Object.keys(pages[0])) {
    if (key === 'ok' || key === 'response_metadata') continue;
    if (Array.isArray(pages[0][key])) {
      merged[key] = pages.flatMap((p) => p[key] || []);
    } else {
      merged[key] = pages[pages.length - 1][key];
    }
  }
  return merged;
}

function truncate(json, maxItems) {
  if (!maxItems || typeof json !== 'object' || json === null) return json;
  const out = Array.isArray(json) ? [...json] : { ...json };
  for (const key of Object.keys(out)) {
    if (Array.isArray(out[key]) && out[key].length > maxItems) {
      out[key] = out[key].slice(0, maxItems);
      out._truncated = true;
    }
  }
  return out;
}

async function main() {
  const opts = parseArgs(process.argv.slice(2));
  const baseData = opts.data || {};
  let url = API_BASE + opts.endpoint;
  let body = encodeBody(baseData);
  if (opts.method === 'GET') {
    if (baseData && Object.keys(baseData).length) url += '?' + body;
    body = null;
  }
  if (opts.dryRun) {
    console.log(
      JSON.stringify({
        dry_run: true,
        method: opts.method,
        url,
        body: body || null,
        paginate: opts.paginate,
        max_items: opts.maxItems || null,
      }),
    );
    return;
  }

  const pages = [];
  for (let page = 0; page < 50; page++) {
    const json = await call(opts, url, body);
    if (!json.ok) fail(json.error || 'unknown_error');
    pages.push(json);
    if (!opts.paginate) break;
    const cursor = (json.response_metadata && json.response_metadata.next_cursor) || '';
    if (!cursor) break;
    const nextData = { ...baseData, cursor };
    body = encodeBody(nextData);
    if (opts.method === 'GET') url = API_BASE + opts.endpoint + '?' + body;
  }

  const result = pages.length === 1 ? pages[0] : { ok: true, pages: pages.length, ...mergePages(pages) };
  console.log(JSON.stringify(truncate(result, opts.maxItems)));
}

main().catch((err) => fail('exception: ' + (err && err.message ? err.message : String(err))));

#!/usr/bin/env node

/**
 * Task-local packager for the slack-api skill.
 *
 * Mirrors .codex/skills/skill-creator/scripts/package_skill.cjs behavior:
 *   1. Validates the skill (same rules as validate_skill.cjs):
 *      - SKILL.md exists with YAML frontmatter
 *      - name is hyphen-case (letters, digits, hyphens)
 *      - description is a single-line string, max 1024 chars
 *      - no "TODO:" anywhere in the skill files
 *   2. Packages the folder into a .skill zip (entries at zip root,
 *      matching `zip -r out .` run from inside the skill folder).
 *
 * The zip is written with a minimal store-only ZIP writer (zero dependencies).
 * Usage: node package_skill_local.cjs
 */

const fs = require('node:fs');
const path = require('node:path');

const SKILL_DIR = path.resolve('slack-api');
const OUT_DIR = path.resolve('dist');
const OUT_FILE = path.join(OUT_DIR, 'slack-api.skill');

// ---------- validation (mirrors validate_skill.cjs) ----------

function getAllFiles(dir, list = []) {
  for (const name of fs.readdirSync(dir)) {
    const p = path.join(dir, name);
    if (fs.statSync(p).isDirectory()) {
      if (!['node_modules', '.git', '__pycache__'].includes(name)) getAllFiles(p, list);
    } else {
      list.push(p);
    }
  }
  return list;
}

function validate(dir) {
  if (!fs.existsSync(dir) || !fs.statSync(dir).isDirectory()) {
    return 'Path is not a directory: ' + dir;
  }
  const mdPath = path.join(dir, 'SKILL.md');
  if (!fs.existsSync(mdPath)) return 'SKILL.md not found';
  const content = fs.readFileSync(mdPath, 'utf8');
  if (!content.startsWith('---')) return 'No YAML frontmatter found';
  const parts = content.split('---');
  if (parts.length < 3) return 'Invalid frontmatter format';
  const fm = parts[1];
  const nameMatch = fm.match(/^name:\s*(.+)$/m);
  const descMatch = fm.match(/^description:\s*(?:'([^']*)'|"([^"]*)"|(.+))$/m);
  if (!nameMatch) return 'Missing "name" in frontmatter';
  if (!descMatch) return 'Description must be a single-line string: description: ...';
  const name = nameMatch[1].trim();
  const description = (
    descMatch[1] !== undefined ? descMatch[1] : descMatch[2] !== undefined ? descMatch[2] : descMatch[3] || ''
  ).trim();
  if (description.includes('\n')) return 'Description must be a single line (no newlines)';
  if (!/^[a-z0-9-]+$/.test(name)) return 'Name "' + name + '" should be hyphen-case';
  if (description.length > 1024) return 'Description is too long (max 1024)';
  for (const f of getAllFiles(dir)) {
    if (fs.readFileSync(f, 'utf8').includes('TODO:')) {
      return 'Unresolved TODO in ' + path.relative(dir, f);
    }
  }
  return null;
}

// ---------- minimal store-only ZIP writer ----------

const CRC_TABLE = (() => {
  const t = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c;
  }
  return t;
})();

function crc32(buf) {
  let c = -1;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ -1) >>> 0;
}

function dosDateTime(d) {
  return {
    time: (d.getHours() << 11) | (d.getMinutes() << 5) | (d.getSeconds() >> 1),
    date: ((d.getFullYear() - 1980) << 9) | ((d.getMonth() + 1) << 5) | d.getDate(),
  };
}

function packZip(entries) {
  const chunks = [];
  const central = [];
  let offset = 0;
  for (const { name, data, mode } of entries) {
    const nameBuf = Buffer.from(name, 'utf8');
    const crc = crc32(data);
    const { time, date } = dosDateTime(new Date());

    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0); // local file header signature
    local.writeUInt16LE(20, 4); // version needed
    local.writeUInt16LE(0, 6); // flags
    local.writeUInt16LE(0, 8); // method: store
    local.writeUInt16LE(time, 10);
    local.writeUInt16LE(date, 12);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(data.length, 18); // compressed size
    local.writeUInt32LE(data.length, 22); // uncompressed size
    local.writeUInt16LE(nameBuf.length, 26);
    local.writeUInt16LE(0, 28); // extra field length
    chunks.push(local, nameBuf, data);

    const entryOffset = offset;
    offset += local.length + nameBuf.length + data.length;

    const cd = Buffer.alloc(46);
    cd.writeUInt32LE(0x02014b50, 0); // central directory signature
    cd.writeUInt16LE(20, 4); // version made by
    cd.writeUInt16LE(20, 6); // version needed
    cd.writeUInt16LE(0, 8); // flags
    cd.writeUInt16LE(0, 10); // method: store
    cd.writeUInt16LE(time, 12);
    cd.writeUInt16LE(date, 14);
    cd.writeUInt32LE(crc, 16);
    cd.writeUInt32LE(data.length, 20);
    cd.writeUInt32LE(data.length, 24);
    cd.writeUInt16LE(nameBuf.length, 28);
    cd.writeUInt16LE(0, 30); // extra field length
    cd.writeUInt16LE(0, 32); // file comment length
    cd.writeUInt16LE(0, 34); // disk number start
    cd.writeUInt16LE(0, 36); // internal attributes
    cd.writeUInt32LE(mode !== undefined ? (mode & 0xffff) << 16 : 0, 38); // external attributes (unix mode)
    cd.writeUInt32LE(entryOffset, 42); // local header offset
    central.push(cd, nameBuf);
  }

  const cdStart = offset;
  const cdSize = central.reduce((n, b) => n + b.length, 0);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0); // end of central directory signature
  eocd.writeUInt16LE(0, 4); // disk number
  eocd.writeUInt16LE(0, 6); // cd start disk
  eocd.writeUInt16LE(entries.length, 8); // entries on this disk
  eocd.writeUInt16LE(entries.length, 10); // total entries
  eocd.writeUInt32LE(cdSize, 12);
  eocd.writeUInt32LE(cdStart, 16);
  eocd.writeUInt16LE(0, 20); // comment length
  return Buffer.concat([...chunks, ...central, eocd]);
}

// ---------- main ----------

const validationError = validate(SKILL_DIR);
if (validationError) {
  console.error('ERROR validation failed: ' + validationError);
  process.exit(1);
}
console.log('OK skill is valid');

const entries = [];
for (const dir of ['scripts/', 'references/']) {
  entries.push({ name: dir, data: Buffer.alloc(0), mode: 0o755 });
}
for (const f of getAllFiles(SKILL_DIR)) {
  const rel = path.relative(SKILL_DIR, f).split(path.sep).join('/');
  entries.push({ name: rel, data: fs.readFileSync(f), mode: /\.cjs$/.test(f) ? 0o755 : 0o644 });
}

fs.mkdirSync(OUT_DIR, { recursive: true });
fs.writeFileSync(OUT_FILE, packZip(entries));
console.log('OK packaged skill to: ' + OUT_FILE);
for (const e of entries) {
  console.log('  - ' + (e.name.endsWith('/') ? e.name : e.name + ' (' + e.data.length + ' bytes)'));
}

