console.log('OK skill is valid');

const entries = [];
for (const dir of ['scripts/', 'references/']) {
  entries.push({ name: dir, data: Buffer.alloc(0), mode: 0o755 });
}
for (const f of getAllFiles(SKILL_DIR)) {
  const rel = path.relative(SKILL_DIR, f).split(path.sep).join('/');
  entries.push({ name: rel, data: fs.readFileSync(f), mode: /\.cjs$/.test(f) ? 0o755 : 0o644 });
}

fs.mkdirSync(OUT_DIR, { recursive: true });
fs.writeFileSync(OUT_FILE, packZip(entries));
console.log('OK packaged skill to: ' + OUT_FILE);
for (const e of entries) {
  console.log('  - ' + (e.name.endsWith('/') ? e.name : e.name + ' (' + e.data.length + ' bytes)'));
}
